def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    # Asymmetric updates: donate gives +0.4, not donate gives -0.5
    if action == 'donate':
        update = 0.4
    else:
        update = -0.5
    # Recency weight: linearly increase from 0.1 to 1.0 over rounds 1-30
    weight = min(1.0, (round_num + 1) / 30.0)  # +1 to avoid zero at round 0
    new_rep = current_reputation + weight * update
    # Clamp to valid range
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Compute own donation rate from personal history (indirect reciprocity)
    if len(my_history) > 0:
        donations = sum(1 for _, action in my_history if action == 'donate')
        own_rate = donations / len(my_history)
    else:
        own_rate = 0.5  # neutral initial starting point
    # Base threshold: more generous if we have donated more often
    base_threshold = 0.5 - 0.4 * own_rate  # ranges 0.1 to 0.5
    # Adjust for round: later rounds are more forgiving
    if round_num > 20:
        threshold = base_threshold * 0.5
    else:
        threshold = base_threshold * 1.2
    # Clamp threshold to reasonable range
    threshold = max(-0.5, min(0.8, threshold))
    return recipient_reputation > threshold

